12	/// One book, as the `books` Dataset holds it.
13	#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
14	pub struct Book {
15	    /// The book's title.
16	    #[schemars(length(min = 1))]
17	    pub title: String,
18	    /// Pounds, an exact decimal kept as text.
19	    #[schemars(regex(pattern = r"^\d+\.\d{2}$"))]
20	    pub price: String,
21	    /// The number in stock.
22	    pub in_stock: u32,
23	    /// One to five stars.
24	    #[schemars(range(min = 1, max = 5))]
25	    pub rating: u8,
26	    /// The page's final URL.
27	    pub url: String,
