49	/// Scenario 05's crawl and the handles a program needs to run it and read it.
50	pub struct BooksCrawl {
51	    /// The declaration: three Labels, one handler each.
52	    pub crawl: Crawl<'static>,
53	    /// The Dataset of books, keyed by URL.
54	    pub books: Dataset<Book>,
55	    /// The seed's Label.
56	    pub home: Label<()>,
57	    /// A book page's Label, for a test of its handler alone.
58	    pub book: Label<BookPayload>,
59	}
