61	impl BooksCrawl {
62	    /// The crawl's seeds. Staying on books.toscrape.com is the default scope (the seed's host),
63	    /// and robots.txt, one request at a time with a second between starts and backing off on 429
64	    /// are the default Politeness.
65	    pub fn seeds(&self) -> [Seed; 1] {
66	        [Seed::new("https://books.toscrape.com/", &self.home, ())]
67	    }
68	}
