70	const RATINGS: [&str; 5] = ["One", "Two", "Three", "Four", "Five"];
71	
72	/// The text between `before` and `after`.
73	fn between<'t>(text: &'t str, before: &str, after: &str) -> Option<&'t str> {
74	    let (_, rest) = text.split_once(before)?;
75	    Some(rest.split_once(after)?.0)
76	}
